from pathlib import Path

path = Path('/home/ubuntu/mineirada-replica/client/src/App.tsx')
text = path.read_text()

new_functions = r'''
function RecipesPage({ data, setData }: { data: typeof initialData; setData: (value: typeof initialData) => void }) {
  const [modal, setModal] = useState(false);
  const [query, setQuery] = useState("");
  const [form, setForm] = useState<RecordItem>({ product: "", name: "", batchSize: "", yieldPct: "100", lossPct: "0", temp: "", shelf: "180", instructions: "" });
  const recipes = data.recipes.filter((r) => Object.values(r).join(" ").toLowerCase().includes(query.toLowerCase()));
  const save = (e: FormEvent) => { e.preventDefault(); setData({ ...data, recipes: [{ ...form, status: "Ativa", cost: "—" }, ...data.recipes] }); setModal(false); setForm({ product: "", name: "", batchSize: "", yieldPct: "100", lossPct: "0", temp: "", shelf: "180", instructions: "" }); };
  return <div className="page-content"><PageHeader title="Receitas / BOM" description={`${recipes.length} receitas`}><Button icon={Plus} onClick={() => setModal(true)}>Nova Receita</Button></PageHeader><div className="toolbar"><div className="search-box"><Search size={16} /><input placeholder="Buscar..." value={query} onChange={(e) => setQuery(e.target.value)} /></div></div><div className="panel table-panel"><Table columns={["Nome", "Produto", "Tamanho do Lote", "Custo/kg", "Status"]} rows={recipes.map((r) => [r.name || "—", r.product || "—", r.batchSize ? `${r.batchSize} kg` : "—", r.cost || "—", <Pill tone="success">{r.status || "Ativa"}</Pill>])} empty="Nenhuma receita cadastrada." /></div>{modal && <Modal title="Nova Receita" onClose={() => setModal(false)} wide><form className="modal-form" onSubmit={save}><Field label="Produto *"><SelectInput value={form.product as string} onChange={(v) => setForm({ ...form, product: v })}><option value="">Selecione o produto</option><option value="Produto cadastrado">Produto cadastrado</option></SelectInput></Field><Field label="Nome da Receita *"><TextInput value={form.name as string} onChange={(v) => setForm({ ...form, name: v })} /></Field><div className="form-grid"><Field label="Tamanho do Lote (kg) *"><TextInput value={form.batchSize as string} onChange={(v) => setForm({ ...form, batchSize: v })} type="number" /></Field><Field label="Rendimento (%)"><TextInput value={form.yieldPct as string} onChange={(v) => setForm({ ...form, yieldPct: v })} type="number" /></Field></div><div className="form-grid three"><Field label="Perda (%)"><TextInput value={form.lossPct as string} onChange={(v) => setForm({ ...form, lossPct: v })} type="number" /></Field><Field label="Temp. (°C)"><TextInput value={form.temp as string} onChange={(v) => setForm({ ...form, temp: v })} type="number" /></Field><Field label="Validade (dias)"><TextInput value={form.shelf as string} onChange={(v) => setForm({ ...form, shelf: v })} type="number" /></Field></div><Field label="Instruções"><textarea className="input textarea" value={form.instructions as string} onChange={(e) => setForm({ ...form, instructions: e.target.value })} /></Field><div className="modal-actions"><Button variant="outline" onClick={() => setModal(false)}>Cancelar</Button><Button type="submit" icon={Check}>Criar</Button></div></form></Modal>}</div>;
}

function DataBackupPage() {
  const [password, setPassword] = useState("");
  const [confirm, setConfirm] = useState("");
  const [file, setFile] = useState<File | null>(null);
  const exportBackup = () => { if (password.length < 12 || password !== confirm) { window.alert("Defina e confirme uma senha com no mínimo 12 caracteres."); return; } const data = localStorage.getItem("mineirada_replica_data") || JSON.stringify(initialData); const blob = new Blob([JSON.stringify({ version: 1, exportedAt: new Date().toISOString(), data: JSON.parse(data) }, null, 2)], { type: "application/json" }); const url = URL.createObjectURL(blob); const anchor = document.createElement("a"); anchor.href = url; anchor.download = "mineirada-backup.json"; anchor.click(); URL.revokeObjectURL(url); };
  const restore = () => { if (!file || password.length < 12 || password !== confirm) { window.alert("Escolha um arquivo e informe a senha de proteção confirmada."); return; } const reader = new FileReader(); reader.onload = () => { try { const parsed = JSON.parse(String(reader.result)); if (!parsed.data) throw new Error("backup"); localStorage.setItem("mineirada_replica_data", JSON.stringify(parsed.data)); window.location.reload(); } catch { window.alert("Arquivo de backup inválido."); } }; reader.readAsText(file); };
  return <div className="page-content"><PageHeader title="Dados e Backup" description="Movimente o estado local do sistema com um arquivo completo, protegido e verificável." /><div className="metrics-grid three"><div className="panel info-card"><LockIcon /><h3>Credenciais protegidas</h3><p>As credenciais não são incluídas no arquivo de dados.</p></div><div className="panel info-card"><RefreshCw size={18} /><h3>Restauração segura</h3><p>O arquivo é validado antes de substituir os registros locais.</p></div><div className="panel info-card"><Database size={18} /><h3>Estado local</h3><p>Cadastros e configurações desta instalação podem ser exportados.</p></div></div><div className="panel"><div className="panel-head"><h3>Senha de proteção do backup</h3><KeyRound size={17} /></div><div className="form-grid"><Field label="Senha com no mínimo 12 caracteres"><TextInput type="password" value={password} onChange={setPassword} placeholder="Senha de proteção" /></Field><Field label="Confirme a senha de proteção"><TextInput type="password" value={confirm} onChange={setConfirm} placeholder="Confirme a senha" /></Field></div></div><div className="panel"><div className="panel-head"><div><h3>Exportar todo o sistema</h3><p>Gera um arquivo JSON de restauração com os registros locais.</p></div><Download size={17} /></div><Button icon={Download} onClick={exportBackup}>Exportar backup completo</Button></div><div className="panel"><div className="panel-head"><div><h3>Importar e restaurar</h3><p>Substitui os registros locais pelo conteúdo do backup selecionado.</p></div><Upload size={17} /></div><input className="input" type="file" accept="application/json" onChange={(e) => setFile(e.target.files?.[0] || null)} /><div className="modal-actions"><Button variant="outline" onClick={() => setFile(null)}>Limpar seleção</Button><Button icon={Upload} onClick={restore}>Criar backup e restaurar</Button></div></div></div>;
}
'''

marker = '\nfunction UsersPage()'
if marker not in text:
    raise SystemExit('UsersPage marker not found')
text = text.replace(marker, '\n' + new_functions + marker, 1)
text = text.replace('else if (location === "/engenharia/receitas") content = <PlaceholderPage title="Receitas / BOM" description="Estrutura de materiais e quantidades por produto" />;', 'else if (location === "/engenharia/receitas") content = <RecipesPage {...common} />;', 1)
text = text.replace('else if (location === "/admin/dados") content = <PlaceholderPage title="Dados e Backup" description="Exportação, restauração e governança dos dados" />;', 'else if (location === "/admin/dados") content = <DataBackupPage />;', 1)
path.write_text(text)
print('reference screens inserted')
